What is printed by this self-invoking function?

```javascript
const counter = (function() {
  let privateCount = 0;
  return {
    increment: () => ++privateCount,
    decrement: () => --privateCount,
    getCount: () => privateCount
  };
})();

counter.increment();
counter.increment();
counter.decrement();
console.log(counter.getCount(), typeof privateCount);
```

What does the following snippet output?

```javascript
const person = {
  name: 'Vikram',
  greetRegular: function() {
    return `Hello, ${this.name}`;
  },
  greetArrow: () => {
    return `Hello, ${this.name}`;
  }
};

const greetFn = person.greetRegular;
console.log(person.greetRegular());
console.log(greetFn());
console.log(person.greetArrow());
```

What is the return value of the following `reduce` operation?

```javascript
const numbers = [10, 20, 30, 40];
const result = numbers.reduce((acc, curr, index) => {
  if (index % 2 === 0) acc.push(curr * 2);
  return acc;
}, []);
console.log(result);
```

Given the prototype chain below, what is the output?

```javascript
function Vehicle(brand) {
  this.brand = brand;
}
Vehicle.prototype.getBrand = function() {
  return this.brand;
};

const car = new Vehicle('Tata');
console.log(car.__proto__ === Vehicle.prototype);
console.log(Vehicle.__proto__ === Function.prototype);
console.log(Vehicle.prototype.__proto__ === Object.prototype);
```

